import asyncio,re,core
clients=set()
async def handle(r,w):
    token=None;nick=None;user=None;joined=set();clients.add((w,joined))
    try:
        while True:
            line=await r.readline()
            if not line:break
            p=line.decode(errors='ignore').strip().split(' ',2);cmd=p[0].upper()
            if cmd=='PASS':token=p[1] if len(p)>1 else ''
            elif cmd=='NICK':nick=p[1] if len(p)>1 else 'guest'
            elif cmd=='USER':
                user=core.user_for_token(token)
                if not user: w.write(b':huddle 464 * :Password incorrect\r\n');await w.drain();break
                for n in range(1,6):w.write(f':huddle {n:03d} {nick} :Huddle\r\n'.encode())
                w.write(f':huddle 422 {nick} :MOTD File is missing\r\n'.encode());await w.drain()
            elif cmd=='PING':w.write(b':huddle PONG huddle\r\n');await w.drain()
            elif cmd=='JOIN' and len(p)>1:
                name=p[1];m=re.match(r'^#([^/]+)/(.+)$',name)
                if not m:w.write(f':huddle 403 {nick} {name} :No such channel\r\n'.encode());continue
                ch=core.get_channel(next((x['id'] for x in core.connect().execute('SELECT * FROM channels') if '#'+str(core.get_workspace(str(x['workspace_id']))['slug'])+'/'+x['name']==name),-1))
                if not ch:w.write(f':huddle 403 {nick} {name} :No such channel\r\n'.encode());continue
                joined.add(ch['id']);w.write(f':{nick}!irc@localhost JOIN {name}\r\n: huddle 353 {nick} = {name} :{nick}\r\n: huddle 366 {nick} {name} :End\r\n'.encode());await w.drain()
            elif cmd=='PRIVMSG' and len(p)>2 and joined:
                ch=next(iter(joined));text=p[2].lstrip(':')
                with core.tx() as c:
                    c.execute('INSERT INTO messages(channel_id,author_id,body,created_at) VALUES(?,?,?,?)',(ch,user['id'],text,core.now_iso()));r2=c.execute('SELECT * FROM messages WHERE id=?',(c.lastrowid,)).fetchone();core.emit_event(c,ch,'message.created',{'message':core.message_to_json(r2)})
            elif cmd=='QUIT':break
    finally:clients.discard((w,joined));w.close()
async def main():return await asyncio.start_server(handle,'0.0.0.0',6667)
